describe('Login Page Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display login form correctly on mobile devices', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
  });

  it('should handle mobile-specific form validation errors', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email address');
    cy.get('[data-testid="error-message"]').should('contain', 'Password must be at least 8 characters');
    cy.get('[data-testid="email-input"]').clear();
    cy.get('[data-testid="password-input"]').clear();
    cy.get('[data-testid="login-button"]').click();
    cy.url().should('include', '/dashboard');
  });
});
